import React, { useState, useEffect } from "react";
import MessageInput from "./components/MessageInput";
import ChatWindow from "./components/ChatWindow";
import LoadingIndicator from "./components/LoadingIndicator";
import "./App.css";

function App() {
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(false);

  // Fetch chat history from the backend and sort messages by timestamp
  useEffect(() => {
    fetch("https://api.openai.com/v1/chat/completions")
      .then((res) => res.json())
      .then((data) => {
        if (Array.isArray(data.choices)) {
          setMessages(
            data.choices
              .map((choice) => ({
                text: choice.message.content,
                sender: choice.message.role,
                timestamp: choice.message.timestamp || Date.now(), // Ensure timestamp
              }))
              .sort((a, b) => a.timestamp - b.timestamp) // Sort messages by timestamp
          );
        }
      })
      .catch((error) => console.error("Error fetching messages:", error));
  }, []);

  // Handle message sending and sorting
  const handleSendMessage = async (userMessage) => {
    const newMessage = { text: userMessage, sender: "user", timestamp: Date.now() };

    // Add user message and sort
    setMessages((prevMessages) =>
      [...prevMessages, newMessage].sort((a, b) => a.timestamp - b.timestamp)
    );

    setLoading(true);

    // Fetch AI response
    const aiResponse = await fetchDeepAIResponse(userMessage);
    setLoading(false);

    const aiMessage = { text: aiResponse, sender: "ai", timestamp: Date.now() };

    // Add AI response and sort
    setMessages((prevMessages) =>
      [...prevMessages, aiMessage].sort((a, b) => a.timestamp - b.timestamp)
    );
  };

  // Fetch response from OpenAI API
  const fetchDeepAIResponse = async (userMessage) => {
    try {
      const response = await fetch("https://api.openai.com/v1/chat/completions", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": "Bearer YOUR_ACTUAL_API_KEY", // Replace this with your actual API key
        },
        body: JSON.stringify({
          model: "gpt-4o-mini", // Make sure the model is correct
          messages: [
            { role: "system", content: "You are a helpful assistant." },
            { role: "user", content: userMessage },
          ],
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to fetch response from OpenAI");
      }

      const data = await response.json();
      return data.choices?.[0]?.message?.content || "Sorry, I couldn't generate a response right now.";
    } catch (error) {
      console.error("Error fetching from OpenAI:", error);
      return "Sorry, I couldn't generate a response right now.";
    }
  };

  return (
    <div className="App">
      <ChatWindow messages={messages} />
      {loading ? (
        <LoadingIndicator />
      ) : (
        <MessageInput onSendMessage={handleSendMessage} />
      )}
    </div>
  );
}

export default App;
